text:
html|input:is([type="email"], [type="tel"], [type="text"], [type="password"], [type="url"]) {
  padding-block: initial;
  min-block-size: var(--button-height);
}

html|input[type="number"] {
  margin-inline-start: 4px;
  padding: 1px;
  min-block-size: var(--button-height);

  /* sizes: chars + 8px padding + 1px borders + spin buttons 25+2+10px  */
  &.size2 {
    inline-size: calc(2ch + 55px);
  }
  &.size3 {
    inline-size: calc(3ch + 55px);
  }
  &.size4 {
    inline-size: calc(4ch + 55px);
  }
  &.size5 {
    inline-size: calc(5ch + 55px);
  }

  &::-moz-number-spin-box {
    padding-inline-start: 10px;
  }

  &::-moz-number-spin-up,
  &::-moz-number-spin-down {
    min-inline-size: 25px;
    min-block-size: calc(var(--button-height) * 0.5 - 4px);
    border: 1px solid var(--border-color);
    background-color: var(--button-background-color);
    color: var(--button-text-color);
  }

  &::-moz-number-spin-up:hover,
  &::-moz-number-spin-down:hover {
    background-color: var(--button-hover-background-color);
    color: var(--button-text-color-hover);
  }
}
